body:
**Michael Bayer ([@zzzeek](https://github.com/zzzeek)) wrote:**

Here's that mapping very simply including a suite of just a handful of very basic tests that fail to work correctly under 1.2.10 since multiple mapper inheritance is not supported, normally you would use non-mapped mixins to express multiply-inherited attributes.   so it is unlikely your program is relying very heavily on that structure since it doesn't really work at all from a mapping perspective in any case.

```
from sqlalchemy import *
from sqlalchemy.orm import *
from sqlalchemy.ext.declarative import declarative_base

Base = declarative_base()


class Carriage(Base):
    __tablename__ = 'carriage'

    id = Column(Integer, primary_key=True)
    type = Column(String)

    __mapper_args__ = {"polymorphic_on": type}


class Production(Carriage):
    prod_column = Column(String)
    __mapper_args__ = {"polymorphic_identity": "production"}


class Commodity(Carriage):
    comm_column = Column(String)
    __mapper_args__ = {"polymorphic_identity": "commodity"}


class Oil(Production, Commodity):
    oil_column = Column(String)
    __mapper_args__ = {"polymorphic_identity": "oil"}

import unittest


class TestMultipleInh(unittest.TestCase):
    def setUp(self):
        e = create_engine("sqlite://", echo=True)
        Base.metadata.create_all(e)
        self.session = Session(e)
        self.session.add(Oil(prod_column='p', comm_column='c', oil_column='o'))
        self.session.commit()

    def test_we_can_load_production(self):
        o1 = self.session.query(Production).one()

        assert o1.type == "oil"

    def test_we_can_load_commodity(self):

        # fails
        o1 = self.session.query(Commodity).one()

        assert o1.type == "oil"

    def test_we_can_load_from_either_superclass(self):
        o1 = self.session.query(Production).first()

        o2 = self.session.query(Commodity).first()

        # fails
        assert o1 is o2

    def test_filter(self):
        # fails
        self.session.query(Oil).filter(
            Oil.comm_column == "c"
        ).filter(Oil.prod_column == "p").one()

    def test_we_have_all_attrs(self):
        o1 = self.session.query(Oil).one()

        # fails
        assert o1.comm_column == "c"
        assert o1.prod_column == "p"
        assert o1.oil_column == "o"


if __name__ == '__main__':
    unittest.main()
```
